output_var_cov_kmate_perms <- paste(
  "/global/scratch/users/milesroberts/moi_lab_projects/grenenet-phase2/results/",
  today,
  "/var_cov_perms_kmate.tsv",
  sep = ""
)

# delete previous run
#check_file_exists(output_gt_kmate_perms)
#check_file_exists(output_var_cov_kmate_perms)

# check that directory exists
folder_path <- dirname(output_gt_kmate_perms)
if (!dir.exists(folder_path)) {
  dir.create(folder_path, recursive = TRUE, showWarnings = FALSE)
}

# make list of sites
# for now, ignore some sites
sites <- unique(gsub("_.*", "", colnames(hapfire)))

# number of sign permutations
num_perm = 1:250

# loop over sites
# NOTE: suspected narrow site subset — "unique(sites)[19:31]" runs only sites
# 19-31 (13 of ~31), verbatim from the notebook's current state.
for (site in unique(sites)[19:31]) {
  print(paste("Site:", site))
  hap_site <- hapfire %>% 
    dplyr::select(starts_with(paste(site, "_", sep = "")))
  
  for (exprep in 1:12) {
    print(paste("Rep:", exprep))
    hap_rep <- hap_site %>%
      dplyr::select(ends_with(paste("_", exprep, sep = ""))) %>%
      collect() %>%
      mutate(window = blocks$window) # add block ids
    #filter(row_number() %in% cls_idx) # subset to variant class
    
    # sort names to be in order of generation
    hap_rep <- hap_rep %>%
      relocate(all_of(sort(colnames(hap_rep))))
    
    if (ncol(hap_rep) < 2) {
      print("Need at least two increments. Skipping to next replicate...")
      next
    }
    
    rep_n <- grab_sample_sizes(flower_counts, pool, colnames(hap_rep), 10000, total_flowers)
    
    hap_rep <- cbind(gen0$X0_0_0, hap_rep)
    colnames(hap_rep)[1] = paste(site, "_0_", exprep, sep = "")
    
    for(p in num_perm){
      
      covmat <- covmat_from_pmat(
        pmat = hap_rep %>% select(-window),
        n = rep_n$total_flowers*2,
        correct_for_n = T,
        input_asin_trans = F,
        procedure = "window",
        windows = hap_rep %>% pull(window),
        standard_by_het = F
      )
      
      # save raw var-cov matrix
      covlong <- covmat %>%
        as.data.frame() %>%
        rownames_to_column(var = "A") %>%
        pivot_longer(cols = -A, names_to = "B", values_to = "cov")
      
      covlong$site <- site
      covlong$rep <- exprep
      covlong$class <- "smallindel_sv_snp" #paste(cls, collapse = "_")
      covlong$perm <- p
      append_table(covlong, output_var_cov_kmate_perms)
      
      gt_result <- gt_from_covmat(covmat)
      gt_result$site = site
      gt_result$rep = exprep
      gt_result$perm = p
      gt_result$class = "smallindel_sv_snp" #paste(cls, collapse = "_")
      append_table(gt_result, output_gt_kmate_perms)
      
      rm(gt_result, covmat, covlong); gc()
    }
    rm(hap_rep); gc()
  }
  rm(hap_site); gc()
}
